"""Validate certificate chains generated by the production Ansible PKI tasks."""

import json
import os
import plistlib
import secrets
import subprocess
import sys
from pathlib import Path

import pytest
import yaml
from cryptography import x509
from cryptography.x509.oid import NameOID

ROOT = Path(__file__).resolve().parents[1]


@pytest.mark.parametrize("ipv6_support", [False, True])
def test_server_certificate_chain(tmp_path: Path, ipv6_support: bool):
    """Trust the server's IP identity while preserving the CA's name constraints."""
    pki = generate_certificates(tmp_path, ipv6_support)
    server = str(pki / "certs/198.51.100.20.crt")
    ca = str(pki / "cacert.pem")
    valid = verify_certificate(ca, server, "198.51.100.20")
    assert valid.returncode == 0, valid.stdout + valid.stderr
    wrong_ip = verify_certificate(ca, server, "198.51.100.21")
    assert wrong_ip.returncode != 0
    client = verify_certificate(ca, str(pki / "certs/phone.crt"))
    assert client.returncode == 0, client.stdout + client.stderr
    if ipv6_support:
        ipv6 = verify_certificate(ca, server, "2606:4700::1")
        assert ipv6.returncode == 0, ipv6.stdout + ipv6.stderr
    certificate = x509.load_pem_x509_certificate(Path(server).read_bytes())
    common_name = certificate.subject.get_attributes_for_oid(NameOID.COMMON_NAME)[0].value
    profile = plistlib.loads((tmp_path / "config/apple/phone.mobileconfig").read_bytes())
    ike = profile["PayloadContent"][0]["IKEv2"]
    assert ike["ServerCertificateCommonName"] == common_name
    assert ike["ServerCertificateIssuerCommonName"] == "198.51.100.20"
    assert ike["RemoteIdentifier"] == "198.51.100.20"


def generate_certificates(tmp_path: Path, ipv6_support: bool) -> Path:
    """Run production PKI and profile tasks entirely in a temporary workspace."""
    (tmp_path / "templates").symlink_to(
        ROOT / "roles/strongswan/templates",
        target_is_directory=True,
    )
    production = yaml.safe_load((ROOT / "roles/strongswan/tasks/openssl.yml").read_text())
    playbook = [
        {
            "hosts": "localhost",
            "gather_facts": False,
            "vars_files": [str(ROOT / "roles/strongswan/defaults/main.yml")],
            "tasks": [
                production[0],
                {
                    "ansible.builtin.import_tasks": str(
                        ROOT / "roles/strongswan/tasks/client_configs.yml",
                    ),
                },
            ],
        }
    ]
    playbook_path = tmp_path / "certificates.yml"
    playbook_path.write_text(yaml.safe_dump(playbook))
    pki = tmp_path / "pki"
    variables = {
        "ansible_python_interpreter": sys.executable,
        "ansible_date_time": {"epoch": "1794480000"},
        "IP_subject_alt_name": "198.51.100.20",
        "ansible_default_ipv6": {"address": "2606:4700::1"},
        "ipv6_support": ipv6_support,
        "ipsec_pki_path": str(pki),
        "ipsec_config_path": str(tmp_path / "config"),
        "CA_password": secrets.token_hex(16),
        "p12_export_password": secrets.token_hex(16),
        "keys_clean_all": False,
        "users": ["phone"],
        "algo_server_name": "certificate-test",
        "algo_no_log": True,
    }
    result = subprocess.run(
        [
            sys.executable,
            "-m",
            "ansible.cli.playbook",
            str(playbook_path),
            "-i",
            "localhost,",
            "-c",
            "local",
            "-e",
            json.dumps(variables),
        ],
        cwd=ROOT,
        env={
            **os.environ,
            "ANSIBLE_LOCAL_TEMP": str(tmp_path / "controller"),
            "ANSIBLE_REMOTE_TEMP": str(tmp_path / "remote"),
        },
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=120,
        check=False,
    )
    assert result.returncode == 0, result.stdout + result.stderr
    return pki


def verify_certificate(ca: str, certificate: str, address: str | None = None):
    """Ask OpenSSL to verify the real chain and optional peer IP address."""
    arguments = ["openssl", "verify", "-CAfile", ca]
    if address is not None:
        arguments.extend(["-verify_ip", address])
    return subprocess.run(
        [*arguments, certificate],
        capture_output=True,
        text=True,
        timeout=10,
        check=False,
    )
